SELECT COUNT(*)
FROM tbl_reservation
WHERE bno      = #{bno}
  AND res_date = #{resDate}
  AND status   = 'RESERVED'
  AND NOT (end_time   <= #{startTime}
           OR start_time >= #{endTime})

